export function portalRows(document) { return Object.values(document.rows); }
export function importRows(document, selectedIds) { return selectedIds.map(id => document.rows[id]); }
function classify(row) { return row.amount > 100 ? 'large' : 'small'; }
function processRows(document, selectedIds, fromPortal) {
  const rows = fromPortal ? Object.values(document.rows) : selectedIds.map(id => document.rows[id]);
  for (const row of rows) {
    if (row.classification === '') row.classification = classify(row);
  }
}
export function importDocument(document, selectedIds) { processRows(document, selectedIds, false); }
export function submitPortal(document) { processRows(document, [], true); }

