function classify(row) { return row.amount > 100 ? 'large' : 'small'; }
function applyRules(rows, overwrite) {
  for (const row of rows) {
    if (overwrite || row.classification === '') row.classification = classify(row);
  }
}
export function submit(document) { applyRules(Object.values(document.rows), false); }
export function refresh(document) { applyRules(Object.values(document.rows), true); }
